def findErrorNums(nums):
    n = len(nums)
    dup = -1
    # Mark elements as seen by flipping the sign at index abs(num)-1
    for num in nums:
        idx = abs(num) - 1
        if nums[idx] < 0:
            dup = abs(num)
        else:
            nums[idx] *= -1
    # Find the missing number (the index +1 where value is still positive)
    missing = -1
    for i in range(n):
        if nums[i] > 0:
            missing = i + 1
            break
    return [dup, missing]
